using Microsoft.CodeAnalysis.Text;
using SaferAccessors.Analysis.Extensions;
using SaferAccessors.Analysis.Models;
using System.CodeDom.Compiler;
using System.Text;

namespace SaferAccessors.Analysis.Builders;

internal sealed class AccessorBuilder
{
	internal AccessorBuilder(AccessorModel model)
	{
		this.Model = model;

		using var writer = new StringWriter();
		using var indentWriter = new IndentedTextWriter(writer, "\t");

		indentWriter.WriteLines(
			"""
			// <auto-generated/>
			
			#nullable enable

			""");

		var type = this.Model.Type;
		var boNamespace = type.Namespace;

		if (!string.IsNullOrWhiteSpace(boNamespace))
		{
			indentWriter.WriteLines(
				$"""
				namespace {boNamespace};
				
				""");
		}

		// TODO:
		// Do we want to allow the user to specify the visibility
		// of the generated class, similar to what I do in Rocks?

		// TODO:
		// Need to be cautious about generation a type
		// with a name that already exists in that namespace.
		// Use the naming trick I did in Rocks to get around that.
		indentWriter.WriteLines(
			$$"""
			public static class {{type.Name}}Extensions
			{
			""");

		indentWriter.Indent++;

		foreach (var field in this.Model.Fields)
		{
			FieldAccessorBuilder.Build(indentWriter, field, type);
		}

		indentWriter.Indent--;
		indentWriter.WriteLine("}");

		this.Text = SourceText.From(writer.ToString(), Encoding.UTF8);
		this.FileName = $"{type.FullyQualifiedName.GenerateFileName()}_Accessors.g.cs";
	}

	internal string FileName { get; }
	internal AccessorModel Model { get; }
	internal SourceText Text { get; private set; }
}